          path: "_bmad-output/implementation-artifacts/sprint-status-manager-control-plane-2026-06-28.yaml",
          backlogStories: 1,
          readyStories: 5,
          readyForDevStories: 5,
          activeStories: 0,
          doneStories: 78,
          nextBacklogStoryKey: "6-6-overnight-run-recovery-and-housekeeping",
