test("blocks refill decisions when assignment inventory is unavailable or malformed", () => {
  const unavailable = buildRefillPlan(
    { desiredWorkers: 99 },
    {
      assignmentSummary: {
        ok: false,
        error: "spawnSync node EPERM",
      },
    },
  );
  assert.equal(unavailable.ok, false);
  assert.equal(unavailable.status, "unknown");
  assert.equal(unavailable.summary.desiredWorkers, 6);
  assert.equal(unavailable.summary.dispatchableLanes, null);
  assert.equal(unavailable.blockers[0].code, "assignment-report-unavailable");
  assert.equal(unavailable.summary.sandboxBoundary, true);
  assert.equal(unavailable.blockers[0].failureClass, "sandbox");
  assert.equal(unavailable.blockers[0].sandboxSignatureClass, "node-spawnsync-eperm");
  assert.match(unavailable.blockers[0].nextAction, /rerun the exact same read-only manager command outside the sandbox once/i);
  assert.doesNotMatch(unavailable.blockers[0].message, /spawnSync|EPERM/);
  assert.equal(unavailable.nextActions.length, 0);
  assert.equal(unavailable.summary.workCreationStep, null);

  const emptyJsonSandbox = buildRefillPlan(
    { desiredWorkers: 3 },
    {
      workspaceRunner: () => ({
        ok: false,
        stdout: "",
        stderr: "SyntaxError: Unexpected end of JSON input",
      }),
    },
  );
  assert.equal(emptyJsonSandbox.ok, false);
  assert.equal(emptyJsonSandbox.summary.sandboxBoundary, true);
  assert.equal(emptyJsonSandbox.blockers[0].code, "assignment-report-unavailable");
  assert.equal(emptyJsonSandbox.blockers[0].failureClass, "sandbox");
  assert.equal(emptyJsonSandbox.blockers[0].sandboxSignatureClass, "empty JSON stdout sandbox/process boundary");
  assert.equal(emptyJsonSandbox.blockers[0].safe_rerun, "exact_command_outside_sandbox_when_read_only");
  assert.match(emptyJsonSandbox.blockers[0].nextAction, /rerun the exact same read-only manager command outside the sandbox once/i);

  const malformed = buildRefillPlan(
    { desiredWorkers: -2 },
    {
      assignmentSummary: {
        summary: {
          backlogStatusCounts: {
            assignable: "not-a-count",
            closed: 78,
          },
        },
      },
    },
  );
  assert.equal(malformed.ok, false);
  assert.equal(malformed.summary.desiredWorkers, 0);
  assert.equal(malformed.blockers[0].code, "assignment-report-malformed");
  assert.equal(malformed.summary.workCreationStep, null);

  const previewBacked = buildRefillPlan(
    { desiredWorkers: 4 },
    {
      assignmentSummary: {
        summary: {
          backlogStatusCounts: {
            assignable: "not-a-count",
          },
        },
      },
      dispatchPreview: {
        summary: {
          counts: {
            dispatchable: 0,
            active: 0,
          },
          candidateStateCounts: {
            active: 0,
            closed: 78,
          },
        },
      },
    },
  );
  assert.equal(previewBacked.ok, false);
  assert.equal(previewBacked.status, "blocked");
  assert.equal(previewBacked.summary.dispatchableLanes, 0);
  assert.equal(previewBacked.summary.closedLanes, 0);
  assert.equal(previewBacked.blockers[0].code, "source-evidence-missing");
});

