test("unverified pointer receipt metadata routes to C-m-only submit repair", () => {
  const stateRoot = mkdtempSync(join(tmpdir(), "manager-worker-receipt-unverified-progress-"));
  try {
    ledgerCommand({ command: "init", runId: "manager-test", stateRoot });
    const progressStatus = buildWorkerProgressStatus(
      { runId: "manager-test", stateRoot },
      {
        now: "2026-06-29T00:03:00.000Z",
        workerStatus: {
          summary: {
            workers: [
              {
                workerId: "codex-1",
                owner: "manager-test/codex-1",
                runId: "manager-test",
                sessionName: "codex-1",
                state: "active",
                assignmentId: "lane-1",
                taskId: "task-1",
                recoveryState: "handoff_sent",
                lastHeartbeatAt: "2026-06-29T00:00:00.000Z",
              },
            ],
          },
        },
        assignmentSummary: { summary: { laneAssignments: [{ assignmentId: "lane-1", owner: "manager-test", heartbeat: "2026-06-29T00:00:00.000Z" }] } },
        checkpoints: [],
        questions: [],
        events: [
          {
            eventId: "receipt",
            actor: "manager",
            eventType: "worker_pointer_receipt_unverified",
            timestamp: "2026-06-29T00:02:00.000Z",
            summary: "receipt unverified",
            sourceRefs: ["assignment:lane-1", "worker:codex-1", "receipt:unverified", "receipt:repaired"],
          },
        ],
      },
    );

    assert.equal(progressStatus.status, "attention");
    assert.equal(progressStatus.summary.workerProgress[0].progressState, "pointer_receipt_unverified");
    assert.equal(progressStatus.nextActions[0].code, "worker-submit-pending-progress-signal");
    assert.match(progressStatus.nextActions[0].nextAction, /manager-worker-submit-pending\.mjs --summary-json --worker-id 'codex-1' --session-name 'codex-1' --assignment-id 'lane-1' --task-id 'task-1'/);

    const submitPreview = buildWorkerSubmitPendingPlan(
      { runId: "manager-test", stateRoot },
      { progressStatus },
    );
    assert.equal(submitPreview.status, "ready");
    assert.equal(submitPreview.summary.planned, 1);
    assert.equal(submitPreview.summary.requests[0].workerId, "codex-1");
    assert.equal(submitPreview.summary.requests[0].progressState, "pointer_receipt_unverified");
    assert.equal(submitPreview.summary.continuousSelection.code, "continuous-worker-submit-pending");
    assert.equal(submitPreview.summary.continuousSelection.mutationClass, "manager_owned_worker_enter_only");
    assert.equal(submitPreview.summary.continuousSelection.allowed, true);
    assert.equal(submitPreview.summary.continuousSelection.status, "ready");
    assert.ok(submitPreview.summary.continuousSelection.targetComponents.includes("worker:codex-1"));
    assert.ok(submitPreview.summary.continuousSelection.targetComponents.includes("assignment:lane-1"));
    assert.equal(submitPreview.summary.transport.submitKey, "C-m");

    const reassignedSubmitPreview = buildWorkerSubmitPendingPlan(
      {
        runId: "manager-test",
        stateRoot,
        workerId: "codex-1",
        sessionName: "codex-1",
        assignmentId: "lane-1",
        taskId: "task-1",
      },
      {
        progressStatus: {
          status: "attention",
          summary: {
            workerProgress: [
              {
                workerId: "codex-1",
                sessionName: "codex-1",
                assignmentId: "lane-2",
                taskId: "task-2",
                progressState: "pointer_receipt_unverified",
                checkpointCount: 0,
                questionCount: 0,
              },
            ],
          },
        },
      },
    );
    assert.equal(reassignedSubmitPreview.status, "ready");
    assert.equal(reassignedSubmitPreview.summary.requests.length, 0);
  } finally {
    rmSync(stateRoot, { recursive: true, force: true });
  }
});

