test("runtime readiness gates continuous apply to explicit existing manager gates", () => {
  assert.ok(MANAGER_RUNTIME_OPERATIONAL_MODES.includes("continuous_apply"));
  assert.ok(MANAGER_RUNTIME_OPERATIONAL_MODES.includes("continuous_dry_run"));

  const selectedAction = {
    code: "continuous-worker-progress-signal",
    mutationClass: "manager_owned_worker_progress_signal",
    targetComponents: ["run:manager-test", "worker:codex-1", "assignment:lane-1"],
  };
  const ready = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { workerMutationAllowed: true },
      selectedAction,
    },
  );
  assert.equal(ready.status, "ready");
  assert.equal(ready.summary.allowedExecutionMode, "continuous_apply_existing_gates");
  assert.equal(ready.summary.gates.workerMutation, "existing_gate_only");
  assert.equal(ready.summary.gates.delivery, "blocked_or_not_requested");
  assert.equal(ready.summary.rawPayloadRetained, false);

  for (const mutationClass of ["manager_owned_worker_code_review_delegation", "manager_owned_worker_review_feedback"]) {
    const reviewMutationReady = buildRuntimeReadinessPlan(
      { runtimeMode: "continuous_apply" },
      {
        cycleStatus: "attention",
        cycleOk: true,
        usage: { state: "normal" },
        resources: { state: "normal" },
        preflight: { status: "ready", blockerCount: 0, blockers: [] },
        continuation: { workerMutationAllowed: true },
        selectedAction: {
          code: `continuous-${mutationClass}`,
          mutationClass,
          targetComponents: ["run:manager-test", "worker:codex-reviewer", "assignment:lane-review"],
        },
      },
    );
    assert.equal(reviewMutationReady.status, "ready");
    assert.equal(reviewMutationReady.summary.gates.workerMutation, "existing_gate_only");
  }

  const laneAdvanceReady = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { laneAdvanceAllowed: true },
      selectedAction: {
        code: "continuous-lane-advance-apply",
        mutationClass: "lane_advancement_heartbeat_metadata_only",
        targetComponents: ["run:manager-test", "assignment:lane-review-ready"],
      },
    },
  );
  assert.equal(laneAdvanceReady.status, "ready");
  assert.equal(laneAdvanceReady.summary.gates.laneAdvance, "existing_gate_only");
  assert.equal(laneAdvanceReady.summary.gates.delivery, "blocked_or_not_requested");
  assert.equal(laneAdvanceReady.summary.gates.cleanup, "blocked");

  const laneAdvanceMissingTarget = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { laneAdvanceAllowed: true },
      selectedAction: {
        code: "continuous-lane-advance-apply",
        mutationClass: "lane_advancement_heartbeat_metadata_only",
        targetComponents: ["assignment:lane-review-ready"],
      },
    },
  );
  assert.equal(laneAdvanceMissingTarget.status, "blocked");
  assert.ok(laneAdvanceMissingTarget.blockers.some((blocker) => blocker.code === "lane-advance-target-not-proven"));

  const laneAdvanceGateMissing = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { laneAdvanceAllowed: false },
      selectedAction: {
        code: "continuous-lane-advance-apply",
        mutationClass: "lane_advancement_heartbeat_metadata_only",
        targetComponents: ["run:manager-test", "assignment:lane-review-ready"],
      },
    },
  );
  assert.equal(laneAdvanceGateMissing.status, "blocked");
  assert.ok(laneAdvanceGateMissing.blockers.some((blocker) => blocker.code === "lane-advance-gate-not-proven"));

  const refillApplyReady = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { refillApplyAllowed: true },
      selectedAction: {
        code: "continuous-refill-apply",
        mutationClass: "local_bmad_refill_artifacts",
      },
    },
  );
  assert.equal(refillApplyReady.status, "ready");
  assert.equal(refillApplyReady.summary.gates.refillArtifactApply, "existing_gate_only");
  assert.equal(refillApplyReady.summary.gates.dispatchApply, "blocked_or_not_requested");
  assert.equal(refillApplyReady.summary.gates.delivery, "blocked_or_not_requested");

  const refillApplyGateMissing = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "normal" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: {},
      selectedAction: {
        code: "continuous-refill-apply",
        mutationClass: "local_bmad_refill_artifacts",
      },
    },
  );
  assert.equal(refillApplyGateMissing.status, "blocked");
  assert.ok(refillApplyGateMissing.blockers.some((blocker) => blocker.code === "refill-apply-gate-not-proven"));

  const blocked = buildRuntimeReadinessPlan(
    { runtimeMode: "continuous_apply" },
    {
      cycleStatus: "attention",
      cycleOk: true,
      usage: { state: "unknown" },
      resources: { state: "normal" },
      preflight: { status: "ready", blockerCount: 0, blockers: [] },
      continuation: { workerMutationAllowed: false },
      selectedAction,
    },
  );
  assert.equal(blocked.status, "blocked");
  assert.ok(blocked.blockers.some((blocker) => blocker.code === "usage-not-ready"));
  assert.ok(blocked.blockers.some((blocker) => blocker.code === "worker-mutation-gate-not-proven"));
});

test("manager run loop preserves worker retirement reassignment proof in dogfood packet", async () => {
  const stateRoot = mkdtempSync(join(tmpdir(), "manager-run-loop-retire-proof-"));
  try {
    const packets = [];
    const selectedAction = {
      code: "continuous-worker-retire",
      mutationClass: "manager_owned_worker_retire",
      authority: "manager-owned-worker-retire-after-recovery-existing-gates",
      targetKey: "assignment:lane-1|run:manager-test|worker:codex-1",
      targetComponents: ["assignment:lane-1", "run:manager-test", "worker:codex-1"],
      workerRetirementReassignment: {
        schemaVersion: "worker_retirement_reassignment.v1",
        basis: "recovery_submit_unanswered",
        allowedMutation: "manager_owned_worker_session_retire_only",
        retirementGate: "manager-worker-retire-existing-gates",
        reassignmentGate: "manager-owned-lease-reassignment",
        recoveryPath: "warm_or_reuse_capacity_then_reassign_only_after_owner_and_lease_evidence",
        reassignmentBoundary: "worker retirement does not take over, reassign, dispatch, deliver, clean up, call providers, or retain raw payloads",
        commandFamily: "manager-worker-retire",
        commandScope: "worker-id:codex-1|assignment-id:lane-1",
        commandAllowed: true,
        nextManagerAction: "manager-worker-retire dry-run (worker-id:codex-1|assignment-id:lane-1)",
        stopLines: ["no assignment takeover", "no dispatch apply", "no delivery or cleanup mutation", "no provider calls or secrets"],
        targetComponents: ["assignment:lane-1", "run:manager-test", "worker:codex-1"],
        rawPayloadRetained: false,
      },
    };

    await runManagerRunLoop(
      {
        runId: "manager-test",
        stateRoot,
        maxIterations: 1,
        summaryJson: true,
        runtimeMode: "continuous_dry_run",
      },
      {
        buildPreflight: () => ({ ok: true, status: "ready", summary: {}, blockers: [], warnings: [] }),
        buildContinuousRunPlan: () => ({
          ok: true,
          status: "attention",
          summary: {
            workerCounts: { active: 1, warm: 0, paused: 0 },
            usageState: "normal",
            resourceState: "normal",
            selectedAction,
            applySelectedAction: null,
            runtimeReadiness: { allowedExecutionMode: "continuous_dry_run" },
          },
          blockers: [],
          warnings: [],
          nextActions: [],
        }),
        executeContinuousSelectedAction: () => ({ ok: true, status: "attention", summary: {}, blockers: [], warnings: [], nextActions: [], continueLoop: false }),
        writePacket: (packet) => packets.push(packet),
        sleep: async () => {},
      },
    );

    assert.equal(packets.length, 1);
    assert.equal(packets[0].summary.selectedAction.code, "continuous-worker-retire");
    assert.equal(packets[0].summary.selectedAction.workerRetirementReassignment.schemaVersion, "worker_retirement_reassignment.v1");
    assert.equal(packets[0].summary.selectedAction.workerRetirementReassignment.rawPayloadRetained, false);
    assert.equal(packets[0].summary.applySelectedAction, null);
    assert.doesNotMatch(JSON.stringify(packets[0].summary.selectedAction.workerRetirementReassignment), /capture-pane|provider payload retained|reasoning trace retained|raw prompt retained/i);
  } finally {
    rmSync(stateRoot, { recursive: true, force: true });
  }
});

test("runtime parser rejects empty modes and duplicate exact target flags", () => {
  assert.throws(
    () => parseCommonArgs(["--runtime-mode", ""]),
    /--runtime-mode requires a value/,
  );
  assert.throws(
    () => parseCommonArgs(["--runtime-mode="]),
    /--runtime-mode requires a non-empty value/,
  );
  for (const flag of ["--worker-id", "--session-name", "--assignment-id", "--task-id"]) {
    assert.throws(
      () => parseCommonArgs([flag, "A", flag, "B"]),
      new RegExp(`${flag} may only be provided once`),
    );
  }
});

test("continuous execution separates dry-run proof from apply mutation", () => {
  const selected = {
    code: "continuous-worker-progress-signal",
    dryRunCommand: "node ./scripts/manager-worker-progress-signal.mjs --summary-json --worker-id codex-1",
    mutationClass: "manager_owned_worker_progress_signal",
    targetComponents: ["assignment:lane-1", "worker:codex-1"],
    targetKey: "assignment:lane-1|worker:codex-1",
  };
  const applySelected = {
    ...selected,
    applyCommand: "node ./scripts/manager-worker-progress-signal.mjs --summary-json --worker-id codex-1 --apply",
  };
  const calls = [];
  const proofPacket = (action) => ({
    ok: true,
    status: "ready",
    continuousSelection: {
      code: action.code,
      mutationClass: action.mutationClass,
      targetComponents: action.targetComponents,
      targetKey: action.targetKey,
      allowed: true,
      status: "ready",
    },
  });

  const dryRunOnly = executeContinuousSelectedAction({
    selected,
    applySelected: null,
    runCommand(command) {
      calls.push(command);
      return { ok: true, packet: proofPacket(selected) };
    },
  });
  assert.equal(dryRunOnly.ok, true);
  assert.equal(calls.length, 1);
  assert.equal(dryRunOnly.summary.apply.status, "skipped_runtime_mode_not_apply_ready");

  calls.length = 0;
  const applied = executeContinuousSelectedAction({
    selected,
    applySelected,
    runCommand(command) {
      calls.push(command);
      return { ok: true, packet: proofPacket(applySelected) };
    },
  });
  assert.equal(applied.ok, true);
  assert.equal(calls.length, 2);
  assert.match(calls[1], /--apply/);

  calls.length = 0;
  const appliedWithoutEchoedApplyProof = executeContinuousSelectedAction({
    selected,
    applySelected,
    runCommand(command) {
      calls.push(command);
      if (!command.includes(" --apply")) return { ok: true, packet: proofPacket(selected) };
      return { ok: true, packet: { ok: true, status: "ready", summary: { results: [{ status: "submitted" }] } } };
    },
  });
  assert.equal(appliedWithoutEchoedApplyProof.ok, true);
  assert.equal(calls.length, 2);
  assert.equal(appliedWithoutEchoedApplyProof.summary.apply.status, "ready");

  calls.length = 0;
  const appliedWithUnrelatedDryRunBlockers = executeContinuousSelectedAction({
    selected,
    applySelected,
    runCommand(command) {
      calls.push(command);
      if (!command.includes(" --apply")) {
        return {
          ok: true,
          packet: {
            ...proofPacket(applySelected),
            blockers: [{ code: "unrelated-question-blocked", message: "A different target is blocked." }],
          },
        };
      }
      return { ok: true, packet: proofPacket(applySelected) };
    },
  });
  assert.equal(appliedWithUnrelatedDryRunBlockers.ok, true);
  assert.equal(calls.length, 2);
  assert.ok(appliedWithUnrelatedDryRunBlockers.summary.dryRun.blockers.some((blocker) => blocker.code === "unrelated-question-blocked"));

  const laneAdvanceSelected = {
    code: "continuous-lane-advance-apply",
    dryRunCommand: "node ./scripts/manager-lane-advance.mjs --summary-json --limit 1 --run-id manager-test",
    mutationClass: "lane_advancement_heartbeat_metadata_only",
    targetComponents: ["assignment:lane-review-ready", "run:manager-test"],
    targetKey: "assignment:lane-review-ready|run:manager-test",
  };
  const laneAdvanceApplySelected = {
    ...laneAdvanceSelected,
    applyCommand: "node ./scripts/manager-lane-advance.mjs --summary-json --limit 1 --run-id manager-test --apply",
  };
  calls.length = 0;
  const laneAdvanceApplied = executeContinuousSelectedAction({
    selected: laneAdvanceSelected,
    applySelected: laneAdvanceApplySelected,
    runCommand(command) {
      calls.push(command);
      return { ok: true, packet: proofPacket(laneAdvanceApplySelected) };
    },
  });
  assert.equal(laneAdvanceApplied.ok, true);
  assert.equal(calls.length, 2);
  assert.match(calls[1], /manager-lane-advance\.mjs/);
  assert.match(calls[1], /--apply/);

  calls.length = 0;
  const laneAdvanceWithoutRunProof = executeContinuousSelectedAction({
    selected: {
      ...laneAdvanceSelected,
      targetComponents: ["assignment:lane-review-ready"],
      targetKey: "assignment:lane-review-ready",
    },
    applySelected: {
      ...laneAdvanceApplySelected,
      targetComponents: ["assignment:lane-review-ready"],
      targetKey: "assignment:lane-review-ready",
    },
    runCommand(command) {
      calls.push(command);
      return {
        ok: true,
        packet: proofPacket({
          ...laneAdvanceApplySelected,
          targetComponents: ["assignment:lane-review-ready"],
          targetKey: "assignment:lane-review-ready",
        }),
      };
    },
  });
  assert.equal(laneAdvanceWithoutRunProof.ok, false);
  assert.equal(laneAdvanceWithoutRunProof.blockers[0].code, "continuous-selected-action-pair-mismatch");
  assert.equal(calls.length, 1);

  calls.length = 0;
  const genericHeartbeatStillDryRunOnly = executeContinuousSelectedAction({
    selected: {
      code: "continuous-generic-heartbeat",
      dryRunCommand: "node ./scripts/manager-lane-advance.mjs --summary-json --limit 1 --run-id manager-test",
      mutationClass: "assignment_heartbeat_metadata_only",
      targetComponents: ["assignment:lane-review-ready", "run:manager-test"],
      targetKey: "assignment:lane-review-ready|run:manager-test",
    },
    applySelected: {
      code: "continuous-generic-heartbeat",
      dryRunCommand: "node ./scripts/manager-lane-advance.mjs --summary-json --limit 1 --run-id manager-test",
      applyCommand: "node ./scripts/manager-lane-advance.mjs --summary-json --limit 1 --run-id manager-test --apply",
      mutationClass: "assignment_heartbeat_metadata_only",
      targetComponents: ["assignment:lane-review-ready", "run:manager-test"],
      targetKey: "assignment:lane-review-ready|run:manager-test",
    },
    runCommand(command) {
      calls.push(command);
      return { ok: true, packet: proofPacket({ code: "continuous-generic-heartbeat", mutationClass: "assignment_heartbeat_metadata_only", targetComponents: ["assignment:lane-review-ready", "run:manager-test"], targetKey: "assignment:lane-review-ready|run:manager-test" }) };
    },
  });
  assert.equal(genericHeartbeatStillDryRunOnly.ok, false);
  assert.equal(genericHeartbeatStillDryRunOnly.blockers[0].code, "continuous-apply-dry-run-only-mutation-class");
  assert.equal(calls.length, 1);

  calls.length = 0;
  const dispatchStillDryRunOnly = executeContinuousSelectedAction({
    selected: {
      code: "continuous-dispatch-apply",
      dryRunCommand: "node ./scripts/codex-workspace.mjs dispatch-next --dry-run --summary-json",
      mutationClass: "assignment_workspace_claim_only",
      targetComponents: ["assignment:lane-ready"],
      targetKey: "assignment:lane-ready",
    },
    applySelected: {
      code: "continuous-dispatch-apply",
      dryRunCommand: "node ./scripts/codex-workspace.mjs dispatch-next --dry-run --summary-json",
      applyCommand: "node ./scripts/codex-workspace.mjs dispatch-next --summary-json --apply",
      mutationClass: "assignment_workspace_claim_only",
      targetComponents: ["assignment:lane-ready"],
      targetKey: "assignment:lane-ready",
    },
    runCommand(command) {
      calls.push(command);
      return { ok: true, packet: proofPacket({ code: "continuous-dispatch-apply", mutationClass: "assignment_workspace_claim_only", targetComponents: ["assignment:lane-ready"], targetKey: "assignment:lane-ready" }) };
    },
  });
  assert.equal(dispatchStillDryRunOnly.ok, false);
  assert.equal(dispatchStillDryRunOnly.blockers[0].code, "continuous-apply-dry-run-only-mutation-class");
  assert.equal(calls.length, 1);
});

